#include <iostream>

int main() {
    // Stream manipulator boolalpha displays true/false as text
    std::cout << std::boolalpha;

    std::cout << "Logical AND (&&)\n"
              << "false && false: " << (false && false) << "\n"
              << "false && true: " << (false && true) << "\n"
              << "true && false: " << (true && false) << "\n"
              << "true && true: " << (true && true) << "\n\n";

    std::cout << "Logical OR (||)\n"
              << "false || false: " << (false || false) << "\n"
              << "false || true: " << (false || true) << "\n"
              << "true || false: " << (true || false) << "\n"
              << "true || true: " << (true || true) << "\n\n";

    std::cout << "Logical NOT (!)\n"
              << "!false: " << (!false) << "\n"
              << "!true: " << (!true) << "\n\n";

    // Demonstrate short-circuit evaluation
    int counter = 10;
    bool condition1 = (false && (++counter > 10)); // ++counter is skipped
    std::cout << "Short-circuit AND: counter = " << counter << ", condition1 = " << condition1 << "\n";

    bool condition2 = (true || (++counter > 10));  // ++counter is skipped
    std::cout << "Short-circuit OR: counter = " << counter << ", condition2 = " << condition2 << "\n";

    return 0;
}
